      // a job told in pictures (see storyBand in tools/build-app-site.js); link = [label, docs article]
      story: {
        kicker: 'A common job',
        title: 'Send a customer your product without sending your design.',
        line: 'A customer wants to see what you make. They don’t need the screws inside it, the board under the cover or the way you built it. Take out what they shouldn’t see, keep the rest light, and export one small GLB. All of it happens on your computer, and the STEP file stays where it is.',
        steps: [
          ['Take out what is inside', 'Select hidden parts looks at the model from every side and picks the parts that never show. Look at them on their own, then delete.', 'Images/apps/meshoptimiser-select-hidden-result.webp'],
          ['Take out the hardware', 'Select one bolt, press Select similar, and every copy goes with it. The picture shows the Fasteners tool of the next version, 0.14, which finds them by shape.', 'Images/apps/meshoptimiser-fasteners.webp'],
          ['Simplify what is left', 'Smart fit swaps a detailed part for a box, a cylinder or blocks that keep its outline. Fill holes closes the bolt holes.', 'Images/apps/meshoptimiser-smart-fit.webp'],
          ['Export one small GLB', 'Names stay, triangles shrink. Export, then open the file once more to check that it holds only what you meant to share.', 'Images/apps/meshoptimiser-export.webp'],
        ],
        foot: 'It is not a lock. The outside of your product is still in the file.',
        link: ['Read the guide', 'make-model-safe-to-send'],
      },
